import heapq
from typing import List


class Solution:
    def maxRemoval(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        if max(nums) >= len(queries):
            return -1
        queries.sort()
        diff = [0] * (n + 1)
        available = []
        applied = 0
        used = 0
        q = 0
        for i in range(n):
            applied += diff[i]
            while q < len(queries) and queries[q][0] <= i:
                heapq.heappush(available, -queries[q][1])
                q += 1
            while applied < nums[i]:
                if not available or -available[0] < i:
                    return -1
                end = -heapq.heappop(available)
                applied += 1
                diff[end + 1] -= 1
                used += 1
        return len(queries) - used

import heapq
from typing import List


class Solution:
    def maxRemoval(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        if sum(nums) >= sum(r - l + 1 for l, r in queries):
            return -1
        queries.sort()
        diff = [0] * (n + 1)
        available = []
        applied = 0
        used = 0
        q = 0
        for i in range(n):
            applied += diff[i]
            while q < len(queries) and queries[q][0] <= i:
                heapq.heappush(available, -queries[q][1])
                q += 1
            while applied < nums[i]:
                if not available or -available[0] < i:
                    return -1
                end = -heapq.heappop(available)
                applied += 1
                diff[end + 1] -= 1
                used += 1
        return len(queries) - used
